http:request.http:query-params:
#[%dw 2.0
output application/java
---
{
  (OrderNumber: payload.filtros.numOrder)
    if (payload.filtros.numOrder? and payload.filtros.numOrder != ""),

  (Status: payload.filtros.status)
    if (payload.filtros.status? and payload.filtros.status != ""),

  (StartDate: payload.filtros.startDate)
    if (payload.filtros.startDate? and payload.filtros.startDate != ""),

  (EndDate: payload.filtros.endDate)
    if (payload.filtros.endDate? and payload.filtros.endDate != ""),

  (CustomerIdType: vars.parameters.CUSTOMER_ID_TYPE)
    if (vars.parameters.CUSTOMER_ID_TYPE? and vars.parameters.CUSTOMER_ID_TYPE != ""),

  (CustomerId: vars.parameters.CUSTOMER_ID)
    if (vars.parameters.CUSTOMER_ID? and vars.parameters.CUSTOMER_ID != ""),

  (Limit: vars.parameters.LIMIT)
    if (vars.parameters.LIMIT?),

  (OffSet: vars.parameters.OFFSET)
    if (vars.parameters.OFFSET?)
}]

